import{_ as t}from"./chunks/qgis-plugin.z4sjB5Si.js";import{_ as n,o as r,c as o,a5 as a}from"./chunks/framework.DvE3tBec.js";const m=JSON.parse('{"title":"New openEO QGIS plugin has been released","description":"","frontmatter":{"news":true,"title":"New openEO QGIS plugin has been released","date":"2025-12-22T00:00:00.000Z","author":"Matthias Mohr, Caro Niebl","aside":false},"headers":[],"relativePath":"news/2025-12-22-new-qgis-plugin.md","filePath":"news/2025-12-22-new-qgis-plugin.md","lastUpdated":1766415117000}'),i={name:"news/2025-12-22-new-qgis-plugin.md"};function s(l,e,p,g,d,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<p>We’re excited to announce the availability of a <strong>new and fully rewritten openEO QGIS plugin</strong>, now ready for broader testing by the community.</p><p><img src="'+t+'" alt="QGIS plugin overview in QGIS with GeoTiff visualization"></p><p>This release represents a major step forward in usability, stability, and feature coverage. The plugin has been redesigned from the ground up and is now <strong>fully integrated into the QGIS Browser</strong>, providing a seamless and intuitive way to access openEO backends and resources directly from QGIS.</p><ul><li><p><strong>QGIS plugin repository:</strong><br><a href="https://plugins.qgis.org/plugins/openeo_plugin/" target="_blank" rel="noreferrer">https://plugins.qgis.org/plugins/openeo_plugin/</a></p></li><li><p><strong>Updated documentation &amp; setup instructions:</strong><br><a href="https://openeo.org/documentation/1.0/qgis/" target="_blank" rel="noreferrer">https://openeo.org/documentation/1.0/qgis/</a></p></li></ul><p>The plugin requires <strong>QGIS 3.40.0 or later</strong> and is expected to be compatible with the upcoming <strong>QGIS 4.0</strong>. It can be downloaded from within QGIS, just search for &#39;openEO&#39; in the plugin manager.</p><h2 id="what-s-new" tabindex="-1">What’s New <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What’s New&quot;">​</a></h2><p>The rewritten plugin introduces a wide range of new features and improvements:</p><ul><li><p><strong>Deep QGIS integration</strong></p><ul><li>Fully integrated into the <strong>QGIS Browser</strong> for easy access</li></ul></li><li><p><strong>Broad API &amp; backend support</strong></p><ul><li>Support for <strong>all openEO API 1.x versions</strong></li><li><strong>openEO Hub</strong> integration</li></ul></li><li><p><strong>Improved authentication</strong></p><ul><li>Support for <strong>OpenID Connect</strong> and <strong>HTTP Basic authentication</strong></li><li>Generally improved and more robust authentication handling, including multi account support</li></ul></li><li><p><strong>Explore and manage openEO resources</strong></p><ul><li>Browse <strong>Collections</strong>, <strong>batch jobs</strong>, and <strong>web services</strong></li><li>Allows for pagination and sorting</li></ul></li><li><p><strong>Rich visualization capabilities</strong></p><ul><li>Visualize batch job results: <ul><li>GeoTIFF</li><li>netCDF (raster only)</li><li>GeoJSON</li><li>GeoParquet</li></ul></li><li>Visualize web services: <ul><li>XYZ</li><li>WMTS</li></ul></li><li>Preview collections when supported by the backend (XYZ, WMTS)</li></ul></li><li><p><strong>STAC integration</strong></p><ul><li>Copy <strong>STAC metadata URLs</strong> and <strong>STAC asset URLs</strong> to easily load other assets via the QGIS layer manager (e.g. CSV) or the QGIS STAC integration (e.g. STAC Items for STAC Collections)</li></ul></li><li><p><strong>Easy data download</strong></p><ul><li>Download assets <strong>all at once</strong> or <strong>individually</strong></li></ul></li></ul><h2 id="call-for-testing-feedback" tabindex="-1">Call for Testing &amp; Feedback <a class="header-anchor" href="#call-for-testing-feedback" aria-label="Permalink to &quot;Call for Testing &amp; Feedback&quot;">​</a></h2><p>We consider the current version <strong>stable and ready to be tested by a broader user audience</strong>. Over the coming weeks, we will collect feedback and apply final refinements, with a <strong>final release planned for the end of January or early February</strong>. We also plan to present the QGIS plugin in one of the next openEO community meeting, please keep an eye on the <a href="https://openeo.org/meetings.html" target="_blank" rel="noreferrer">planned topics</a>.</p><p><strong>Your feedback is highly appreciated!</strong><br> Please share issues, suggestions, or improvements via <a href="https://github.com/Open-EO/openeo-qgis-plugin/issues" target="_blank" rel="noreferrer"><strong>GitHub issues</strong></a>.</p><h2 id="acknowledgements" tabindex="-1">Acknowledgements <a class="header-anchor" href="#acknowledgements" aria-label="Permalink to &quot;Acknowledgements&quot;">​</a></h2><p>The revival and complete reshaping of the openEO QGIS plugin was driven by <strong>Caro Niebl</strong>, an intern at <a href="https://moregeo.it" target="_blank" rel="noreferrer">moreGeo</a>, who has dedicated the past weeks to rethinking and rebuilding the plugin from the ground up.</p><p>This work was funded to a large extent by <a href="https://vito.be" target="_blank" rel="noreferrer">VITO</a>. We would like to sincerely thank them for their support and contribution to the openEO ecosystem.</p><h2 id="this-and-next-year" tabindex="-1">This and Next Year <a class="header-anchor" href="#this-and-next-year" aria-label="Permalink to &quot;This and Next Year&quot;">​</a></h2><p>It has been a great year for openEO. CDSE is making openEO available to a large number of users, and more projects are adopting openEO with more launches expected next year.</p><p>We are looking forward to next year, expecting new releases of the openEO API and openEO processes, and hopefully an adoption as OGC community standard.</p><p>🎄 <strong>Merry Christmas and a Happy New Year to the openEO community!</strong></p>',18)])])}const f=n(i,[["render",s]]);export{m as __pageData,f as default};
